head.b:skin:
html, body, .yt-dark-theme {
  background-color: #0f0f0f !important;
  color: #f1f1f1 !important;
  margin: 0 !important;
  padding: 0 !important;
  font-family: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif !important;
}
/* ==========================================================================
   RivisionTube - YouTube Dark Theme Design System
   ========================================================================== */

:root {
  /* YouTube Official Dark Theme Palette */
  --yt-bg-base: #0f0f0f;
  --yt-bg-surface: #212121;
  --yt-bg-elevated: #272727;
  --yt-bg-input: #121212;
  --yt-bg-hover: #383838;
  --yt-bg-active: #4d4d4d;

  --yt-border: rgba(255, 255, 255, 0.1);
  --yt-border-focus: #3ea6ff;

  --yt-text-primary: #f1f1f1;
  --yt-text-secondary: #aaaaaa;
  --yt-text-muted: #717171;
  --yt-text-inverse: #0f0f0f;

  --yt-red: #ff0000;
  --yt-blue: #3ea6ff;
  --yt-blue-hover: #65b8ff;
  --yt-green: #2ba640;

  /* Typography */
  --font-sans: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  /* Radii & Shadows */
  --radius-xs: 4px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-full: 9999px;

  --yt-shadow: 0 4px 20px rgba(0, 0, 0, 0.6);
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s ease;
}

/* Reset & Global */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body.yt-dark-theme {
  font-family: var(--font-sans);
  background-color: var(--yt-bg-base);
  color: var(--yt-text-primary);
  line-height: 1.4;
  min-height: 100vh;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ==========================================================================
   YouTube Header (Top Bar)
   ========================================================================== */

.yt-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--yt-bg-base);
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  border-bottom: 1px solid var(--yt-border);
}

.yt-header-left {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 220px;
}

.yt-icon-btn {
  background: transparent;
  border: none;
  color: var(--yt-text-primary);
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background var(--transition-fast);
}
.yt-icon-btn:hover {
  background: var(--yt-bg-hover);
}

.yt-brand {
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  text-decoration: none;
}
.yt-brand-title {
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: -0.5px;
  color: #fff;
}
.yt-brand-title span {
  color: var(--yt-red);
}
.yt-badge-country {
  font-size: 0.65rem;
  color: var(--yt-text-muted);
  font-weight: 700;
  margin-left: 2px;
  vertical-align: super;
}

/* YouTube Center Search Bar */
.yt-header-center {
  flex: 1;
  max-width: 680px;
  margin: 0 20px;
}

.yt-search-form {
  display: flex;
  width: 100%;
}

.yt-search-box {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
}

.yt-search-input {
  width: 100%;
  height: 40px;
  background: var(--yt-bg-input);
  border: 1px solid var(--yt-border);
  border-right: none;
  border-radius: 20px 0 0 20px;
  padding: 0 16px;
  color: var(--yt-text-primary);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  outline: none;
  transition: border-color var(--transition-fast);
}
.yt-search-input:focus {
  border-color: var(--yt-blue);
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.5);
}

.yt-clear-input-btn {
  position: absolute;
  right: 12px;
  background: none;
  border: none;
  color: var(--yt-text-muted);
  font-size: 0.85rem;
  cursor: pointer;
}
.yt-clear-input-btn:hover {
  color: #fff;
}

.yt-search-btn {
  width: 64px;
  height: 40px;
  background: var(--yt-bg-elevated);
  border: 1px solid var(--yt-border);
  border-radius: 0 20px 20px 0;
  color: var(--yt-text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background var(--transition-fast);
}
.yt-search-btn:hover {
  background: var(--yt-bg-hover);
}

/* YouTube Right Bar */
.yt-header-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.yt-pill-btn {
  background: var(--yt-bg-elevated);
  border: 1px solid var(--yt-border);
  color: var(--yt-text-primary);
  font-family: var(--font-sans);
  font-size: 0.82rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: background var(--transition-fast);
  white-space: nowrap;
}
.yt-pill-btn:hover {
  background: var(--yt-bg-hover);
}

.yt-cloud-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--yt-bg-elevated);
  border: 1px solid var(--yt-border);
  padding: 5px 12px;
  border-radius: var(--radius-full);
  font-size: 0.78rem;
  color: var(--yt-text-secondary);
}
.yt-cloud-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #717171;
}
.yt-cloud-dot.connected {
  background: var(--yt-green);
  box-shadow: 0 0 8px var(--yt-green);
}
.yt-cloud-btn {
  background: transparent;
  border: none;
  color: var(--yt-blue);
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  padding: 2px 4px;
}
.yt-cloud-btn:hover {
  text-decoration: underline;
}

.yt-user-avatar {
  width: 36px;
  height: 36px;
  background: linear-gradient(135deg, #6366f1, #3ea6ff);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  cursor: pointer;
}

/* ==========================================================================
   YouTube Watch Page Layout (2 Columns)
   ========================================================================== */

.yt-watch-layout {
  max-width: 1750px;
  margin: 0 auto;
  padding: 20px 24px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 420px;
  gap: 24px;
  align-items: start;
}

@media (max-width: 1150px) {
  .yt-watch-layout {
    grid-template-columns: 1fr;
  }
}

/* ==========================================================================
   PRIMARY COLUMN (Left)
   ========================================================================== */

.yt-primary-col {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* Video Player Container */
.yt-player-container {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.player-wrapper {
  position: relative;
  width: 100%;
  padding-top: 56.25%; /* 16:9 Aspect Ratio */
  background: #000;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: 0 10px 35px rgba(0, 0, 0, 0.8);
}

/* Native Fullscreen Mode */
.player-wrapper:fullscreen,
.player-wrapper:-webkit-full-screen {
  padding-top: 0 !important;
  width: 100vw !important;
  height: 100vh !important;
  border-radius: 0 !important;
  background: #000 !important;
}

#youtubePlayerContainer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
#youtubePlayerContainer iframe {
  width: 100%;
  height: 100%;
  border: none;
}

.player-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 24px;
  background: #181818;
}
.placeholder-icon {
  font-size: 48px;
  margin-bottom: 8px;
}
.placeholder-content h4 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.placeholder-content p {
  font-size: 0.85rem;
  color: var(--yt-text-secondary);
  max-width: 400px;
  margin: 0 auto;
}

/* Auto-Stop Completion Overlay */
.clip-completed-overlay {
  position: absolute;
  inset: 0;
  background: rgba(15, 15, 15, 0.95);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 10;
  animation: fadeIn 0.25s ease-out;
}
.clip-completed-overlay.active {
  display: flex;
}

.completed-box {
  text-align: center;
  max-width: 400px;
}
.completed-badge {
  display: inline-block;
  background: var(--yt-green);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 800;
  padding: 4px 14px;
  border-radius: var(--radius-full);
  margin-bottom: 10px;
  letter-spacing: 0.5px;
}
.completed-box h4 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.completed-msg {
  font-size: 0.85rem;
  color: var(--yt-text-secondary);
  margin-bottom: 18px;
}
.completed-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Spaced Repetition Recall Assessment in Overlay */
.sr-recall-card {
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-sm);
  padding: 10px;
  margin-bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.sr-recall-title {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--yt-blue);
}
.sr-recall-actions {
  display: flex;
  gap: 6px;
  justify-content: center;
}
.sr-btn {
  flex: 1;
  font-family: var(--font-sans);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 6px 4px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.sr-btn:hover {
  transform: translateY(-2px);
}
.sr-btn-hard {
  background: rgba(239, 68, 68, 0.2);
  color: #f87171;
  border-color: rgba(239, 68, 68, 0.4);
}
.sr-btn-hard:hover {
  background: #ef4444;
  color: #fff;
}
.sr-btn-good {
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.4);
}
.sr-btn-good:hover {
  background: #10b981;
  color: #fff;
}
.sr-btn-easy {
  background: rgba(234, 179, 8, 0.2);
  color: #facc15;
  border-color: rgba(234, 179, 8, 0.4);
}
.sr-btn-easy:hover {
  background: #eab308;
  color: #000;
}

/* Floating Fullscreen Timeframe Capture Dock (Compact) */
.floating-fullscreen-dock {
  position: absolute;
  bottom: 18px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 25;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.fs-dock-expanded {
  background: rgba(18, 18, 18, 0.94);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.9), 0 0 15px rgba(62, 166, 255, 0.2);
  border-radius: var(--radius-full);
  padding: 5px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.floating-fullscreen-dock:hover .fs-dock-expanded {
  border-color: var(--yt-blue);
  box-shadow: 0 10px 35px rgba(0, 0, 0, 0.95), 0 0 20px rgba(62, 166, 255, 0.3);
}

.fs-dock-header {
  display: flex;
  align-items: center;
  border-right: 1px solid rgba(255, 255, 255, 0.15);
  padding-right: 8px;
}

.fs-dock-badge {
  display: flex;
  align-items: center;
  gap: 5px;
}

.fs-live-time {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--yt-blue);
  letter-spacing: 0.3px;
}

.fs-dock-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.fs-btn {
  font-family: var(--font-sans);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.fs-btn span {
  font-family: var(--font-mono);
  font-size: 0.72rem;
}

.fs-btn-start {
  background: var(--yt-blue);
  color: #000;
}
.fs-btn-start:hover {
  background: var(--yt-blue-hover);
  transform: scale(1.03);
}

.fs-btn-end {
  background: #a855f7;
  color: #fff;
}
.fs-btn-end:hover {
  background: #c084fc;
  transform: scale(1.03);
}

.fs-btn-save {
  background: var(--yt-green);
  color: #fff;
}
.fs-btn-save:hover {
  background: #34d399;
  transform: scale(1.03);
}

.fs-btn-skip {
  background: rgba(239, 68, 68, 0.2);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.4);
}
.fs-btn-skip:hover {
  background: #ef4444;
  color: #fff;
  transform: scale(1.03);
}
.fs-btn-skip.recording {
  background: #dc2626 !important;
  color: #fff !important;
  animation: pulseRed 1.2s infinite ease-in-out;
}

.fs-btn-toggle {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  border: none;
  color: var(--yt-text-secondary);
  font-size: 0.68rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);
  margin-left: 2px;
}
.fs-btn-toggle:hover {
  background: rgba(255, 255, 255, 0.25);
  color: #fff;
}

/* Mini Collapsed Floating Trigger */
.fs-dock-mini-trigger {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--yt-blue), #2563eb);
  border: 1px solid rgba(255, 255, 255, 0.3);
  box-shadow: 0 4px 18px rgba(37, 99, 235, 0.6);
  color: #fff;
  font-size: 1.05rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}
.fs-dock-mini-trigger:hover {
  transform: scale(1.12);
  box-shadow: 0 6px 22px rgba(37, 99, 235, 0.85);
}

/* Hidden State */
.floating-fullscreen-dock.dock-hidden {
  display: none !important;
}

/* Custom Video Controls Bar */
.yt-player-controls-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background: var(--yt-bg-surface);
  border-radius: var(--radius-sm);
  border: 1px solid var(--yt-border);
  flex-wrap: wrap;
  gap: 10px;
}

.yt-ctrl-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.yt-ctrl-btn {
  background: var(--yt-bg-elevated);
  border: 1px solid var(--yt-border);
  color: var(--yt-text-primary);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: background var(--transition-fast);
}
.yt-ctrl-btn:hover {
  background: var(--yt-bg-hover);
}

.yt-time-readout {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--yt-blue);
  margin-left: 6px;
}

.live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--yt-green);
  box-shadow: 0 0 8px var(--yt-green);
}

.yt-ctrl-label {
  font-size: 0.75rem;
  color: var(--yt-text-muted);
}
.yt-speed-btn {
  background: var(--yt-bg-elevated);
  border: 1px solid var(--yt-border);
  color: var(--yt-text-secondary);
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
  cursor: pointer;
}
.yt-speed-btn:hover {
  background: var(--yt-bg-hover);
  color: #fff;
}
.yt-speed-btn.active {
  background: #fff;
  color: #000;
  border-color: #fff;
}

/* ==========================================================================
   YouTube Video Info Box & Action Buttons Row
   ========================================================================== */

.yt-video-info-box {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.yt-video-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  line-height: 1.35;
}

.yt-channel-action-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 4px;
}

.yt-channel-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.yt-channel-avatar {
  width: 42px;
  height: 42px;
  background: #272727;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
}

.yt-channel-meta {
  display: flex;
  flex-direction: column;
}
.yt-channel-name {
  font-size: 0.95rem;
  font-weight: 700;
  color: #fff;
}
.yt-sub-count {
  font-size: 0.78rem;
  color: var(--yt-text-secondary);
}

.yt-action-buttons {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.yt-action-btn {
  background: var(--yt-bg-elevated);
  border: 1px solid var(--yt-border);
  color: var(--yt-text-primary);
  font-family: var(--font-sans);
  font-size: 0.78rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  text-decoration: none;
  transition: background var(--transition-fast);
  white-space: nowrap;
}
.yt-action-btn:hover {
  background: var(--yt-bg-hover);
}

.yt-btn-capture {
  background: rgba(62, 166, 255, 0.15);
  color: var(--yt-blue);
  border-color: rgba(62, 166, 255, 0.35);
}
.yt-btn-capture:hover {
  background: var(--yt-blue);
  color: #000;
}

.yt-btn-capture-end {
  background: rgba(168, 85, 247, 0.15);
  color: #c084fc;
  border-color: rgba(168, 85, 247, 0.35);
}
.yt-btn-capture-end:hover {
  background: #a855f7;
  color: #fff;
}

.yt-btn-save-main {
  background: var(--yt-green);
  color: #fff;
  border-color: var(--yt-green);
}
.yt-btn-save-main:hover {
  background: #34d399;
}

.yt-btn-skip-zone {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
  border-color: rgba(239, 68, 68, 0.4);
}
.yt-btn-skip-zone:hover {
  background: #ef4444;
  color: #fff;
}
.yt-btn-skip-zone.recording {
  background: #dc2626 !important;
  color: #fff !important;
  border-color: #ef4444 !important;
  animation: pulseRed 1.2s infinite ease-in-out;
}

.yt-btn-skip-count {
  background: rgba(239, 68, 68, 0.12);
  color: #fca5a5;
  border-color: rgba(239, 68, 68, 0.35);
  font-size: 0.75rem;
  padding: 5px 12px;
}
.yt-btn-skip-count:hover {
  background: rgba(239, 68, 68, 0.25);
  color: #fff;
}

.yt-btn-quick-skip {
  background: rgba(255, 255, 255, 0.08);
  color: var(--yt-text-secondary);
}
.yt-btn-quick-skip:hover {
  background: rgba(255, 255, 255, 0.18);
  color: #fff;
}

@keyframes pulseRed {
  0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
  70% { box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
  100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}

/* Auto-Skip Zones Pill Strip */
.yt-skip-zones-strip {
  background: #191b22;
  border: 1px dashed rgba(239, 68, 68, 0.4);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.skip-strip-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}
.skip-strip-title {
  font-size: 0.78rem;
  color: #f87171;
}
.skip-strip-hint {
  font-size: 0.7rem;
  color: var(--yt-text-muted);
}

.skip-zones-chips-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.skip-zone-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.3);
  padding: 3px 8px;
  border-radius: var(--radius-full);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: #fca5a5;
}
.skip-zone-chip button {
  background: none;
  border: none;
  color: #f87171;
  cursor: pointer;
  font-weight: bold;
  font-size: 0.75rem;
  line-height: 1;
  padding: 0 2px;
}
.skip-zone-chip button:hover {
  color: #fff;
}

/* ==========================================================================
   YouTube Collapsible Description / Bookmark Deck Box (Compact)
   ========================================================================== */

.yt-description-box {
  background: var(--yt-bg-surface);
  border: 1px solid var(--yt-border);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.yt-desc-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.yt-desc-title {
  font-size: 0.88rem;
  font-weight: 700;
  color: #fff;
}
.yt-desc-badge {
  font-size: 0.68rem;
  background: rgba(62, 166, 255, 0.15);
  color: var(--yt-blue);
  padding: 2px 7px;
  border-radius: var(--radius-full);
  font-weight: 600;
}

.yt-bookmark-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.yt-form-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.yt-form-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.yt-form-group label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--yt-text-secondary);
}
.yt-form-group .req { color: var(--yt-red); }
.yt-form-group .opt { font-size: 0.68rem; color: var(--yt-text-muted); }

.yt-form-input, .yt-form-select, .yt-form-textarea {
  width: 100%;
  background: var(--yt-bg-input);
  border: 1px solid var(--yt-border);
  border-radius: var(--radius-xs);
  color: var(--yt-text-primary);
  font-family: inherit;
  font-size: 0.82rem;
  padding: 6px 9px;
  outline: none;
  transition: var(--transition-fast);
}

.yt-clip-visual {
  margin-top: 8px;
  border-radius: var(--radius-xs);
  overflow: hidden;
  border: 1px solid var(--yt-border);
}
.yt-clip-visual-img {
  width: 100%;
  max-height: 180px;
  object-fit: cover;
  display: block;
}
.yt-btn-read-note {
  background: rgba(168, 85, 247, 0.12);
  border: 1px solid rgba(168, 85, 247, 0.3);
  color: #c084fc;
  font-size: 0.72rem;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 6px;
  transition: var(--transition-fast);
}
.yt-btn-read-note:hover {
  background: rgba(168, 85, 247, 0.25);
  color: #fff;
}
.yt-form-input:focus, .yt-form-select:focus, .yt-form-textarea:focus {
  border-color: var(--yt-blue);
}
.yt-form-textarea {
  resize: vertical;
  min-height: 44px;
}

.yt-link-action {
  background: none;
  border: none;
  color: var(--yt-blue);
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
  padding: 0 4px;
}
.yt-link-action:hover {
  text-decoration: underline;
}

.yt-fetch-transcript-btn {
  background: rgba(56, 189, 248, 0.12) !important;
  color: #38bdf8 !important;
  border: 1px solid rgba(56, 189, 248, 0.3) !important;
  padding: 2px 8px !important;
  border-radius: 12px !important;
  font-weight: 700 !important;
  font-size: 0.74rem !important;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  text-decoration: none !important;
  transition: all var(--transition-fast);
}

.yt-fetch-transcript-btn:hover {
  background: rgba(56, 189, 248, 0.25) !important;
  border-color: rgba(56, 189, 248, 0.6) !important;
  color: #fff !important;
  text-decoration: none !important;
}

.yt-fetch-transcript-btn.loading {
  opacity: 0.6;
  pointer-events: none;
  cursor: wait;
  animation: pulseBtn 1s infinite;
}

@keyframes pulseBtn {
  0% { opacity: 0.5; }
  50% { opacity: 1; }
  100% { opacity: 0.5; }
}

.label-with-action {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* 🎙️ Voice Memo Deck */
.voice-memo-deck {
  background: rgba(255, 255, 255, 0.03);
  border: 1px dashed rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-xs);
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.voice-memo-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.voice-record-btn {
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.4);
  color: #f87171;
  font-family: var(--font-sans);
  font-size: 0.76rem;
  font-weight: 700;
  padding: 5px 12px;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  transition: all var(--transition-fast);
}
.voice-record-btn:hover {
  background: #ef4444;
  color: #fff;
}
.voice-record-btn.recording {
  background: #dc2626 !important;
  color: #fff !important;
  animation: pulseRed 1s infinite ease-in-out;
}
.voice-record-timer {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: #f87171;
  font-weight: 700;
}
.voice-preview-box {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(62, 166, 255, 0.15);
  border: 1px solid rgba(62, 166, 255, 0.35);
  padding: 3px 8px;
  border-radius: var(--radius-full);
}
.voice-play-preview-btn {
  background: none;
  border: none;
  color: var(--yt-blue);
  font-family: var(--font-sans);
  font-size: 0.74rem;
  font-weight: 700;
  cursor: pointer;
}
.voice-play-preview-btn:hover {
  text-decoration: underline;
}
.voice-delete-btn {
  background: none;
  border: none;
  color: #aaa;
  cursor: pointer;
  font-size: 0.72rem;
}
.voice-delete-btn:hover {
  color: var(--yt-red);
}

/* Card Voice Note Play Button */
.yt-btn-play-voice {
  background: rgba(62, 166, 255, 0.12);
  border: 1px solid rgba(62, 166, 255, 0.3);
  color: var(--yt-blue);
  font-family: var(--font-sans);
  font-size: 0.72rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 4px;
  transition: all var(--transition-fast);
}
.yt-btn-play-voice:hover {
  background: var(--yt-blue);
  color: #000;
}

/* Spaced Repetition Due Today Chip & Badges */
.yt-chip-due {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.35);
}
.yt-chip-due:hover, .yt-chip-due.active {
  background: #f59e0b;
  color: #000;
  border-color: #f59e0b;
}
.sr-due-badge {
  background: rgba(245, 158, 11, 0.2);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.4);
  font-size: 0.65rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
  text-transform: uppercase;
}
.sr-level-badge {
  background: rgba(255, 255, 255, 0.08);
  color: var(--yt-text-secondary);
  font-size: 0.65rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
}

.yt-form-submit-row {
  display: flex;
  justify-content: flex-end;
  margin-top: 2px;
}

/* Buttons System */
.yt-btn {
  font-family: var(--font-sans);
  font-size: 0.82rem;
  font-weight: 700;
  padding: 7px 16px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.yt-btn-primary {
  background: var(--yt-blue);
  color: #0f0f0f;
}
.yt-btn-primary:hover {
  background: var(--yt-blue-hover);
}

.yt-btn-secondary {
  background: var(--yt-bg-elevated);
  color: #fff;
  border: 1px solid var(--yt-border);
}
.yt-btn-secondary:hover {
  background: var(--yt-bg-hover);
}

.yt-btn-outline {
  background: transparent;
  color: #fff;
  border: 1px solid var(--yt-border);
}
.yt-btn-outline:hover {
  background: var(--yt-bg-hover);
}

.yt-btn-sm { padding: 5px 10px; font-size: 0.75rem; }
.yt-btn-lg { padding: 8px 18px; font-size: 0.85rem; }

/* ==========================================================================
   SECONDARY COLUMN (Right Sidebar - YouTube Playlist / Up Next Style)
   ========================================================================== */

.yt-secondary-col {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.yt-sidebar-header {
  position: sticky;
  top: 66px;
  background: var(--yt-bg-base);
  z-index: 20;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--yt-border);
}

.yt-sidebar-title-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.yt-sidebar-title-row h3 {
  font-size: 1.05rem;
  font-weight: 700;
  color: #fff;
}
.yt-badge-count {
  font-size: 0.72rem;
  font-weight: 700;
  background: var(--yt-bg-elevated);
  padding: 3px 8px;
  border-radius: var(--radius-full);
  color: var(--yt-text-secondary);
}

/* Horizontal Subject Chips Carousel */
.yt-chips-container {
  overflow-x: auto;
  padding-bottom: 4px;
}
.yt-chips-container::-webkit-scrollbar { height: 4px; }
.yt-chips-container::-webkit-scrollbar-thumb { background: #333; border-radius: 4px; }

.yt-chips-scroll {
  display: flex;
  gap: 8px;
  white-space: nowrap;
}

.yt-chip {
  background: var(--yt-bg-elevated);
  border: 1px solid transparent;
  color: var(--yt-text-primary);
  font-family: var(--font-sans);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
}
.yt-chip:hover {
  background: var(--yt-bg-hover);
}
.yt-chip.active {
  background: #fff;
  color: #0f0f0f;
}

.yt-subfilter-row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.yt-mini-select {
  flex: 1;
  background: var(--yt-bg-input);
  border: 1px solid var(--yt-border);
  color: var(--yt-text-secondary);
  font-size: 0.75rem;
  padding: 5px 8px;
  border-radius: var(--radius-xs);
  outline: none;
}

/* ==========================================================================
   YouTube-Style Video Revision Cards List
   ========================================================================== */

.yt-clips-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.yt-clip-card {
  display: flex;
  gap: 12px;
  padding: 10px;
  border-radius: var(--radius-md);
  background: #1c1f26; /* Soft elegant dark tone, lighter than black */
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.35);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
}

.yt-clip-card:hover {
  background: #262a36; /* Distinct refined slate-blue hover tone */
  border-color: rgba(62, 166, 255, 0.45);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.6), 0 0 15px rgba(62, 166, 255, 0.15);
  transform: translateY(-2px);
}

/* Video Mini Thumbnail */
.yt-clip-thumb {
  position: relative;
  width: 140px;
  height: 80px;
  flex-shrink: 0;
  background: #14161d;
  border-radius: var(--radius-sm);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.yt-thumb-bg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.yt-thumb-tag {
  position: absolute;
  top: 4px;
  left: 4px;
  font-size: 0.62rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
  text-transform: uppercase;
}

.yt-thumb-tag.tag-tricky { background: rgba(244, 63, 94, 0.9); color: #fff; }
.yt-thumb-tag.tag-concept { background: rgba(6, 182, 212, 0.9); color: #fff; }
.yt-thumb-tag.tag-formula { background: rgba(168, 85, 247, 0.9); color: #fff; }
.yt-thumb-tag.tag-trick { background: rgba(245, 158, 11, 0.9); color: #000; }
.yt-thumb-tag.tag-trap { background: rgba(249, 115, 22, 0.9); color: #fff; }
.yt-thumb-tag.tag-doubt { background: rgba(148, 163, 184, 0.9); color: #000; }

.yt-thumb-time {
  position: absolute;
  bottom: 4px;
  right: 4px;
  background: rgba(0, 0, 0, 0.85);
  color: #fff;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 5px;
  border-radius: 3px;
}

/* Card Info Column */
.yt-clip-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-width: 0;
}

.yt-clip-title {
  font-size: 0.88rem;
  font-weight: 600;
  color: #fff;
  line-height: 1.3;
  margin-bottom: 4px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.yt-clip-meta {
  font-size: 0.74rem;
  color: var(--yt-text-secondary);
  display: flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.yt-clip-note {
  font-size: 0.72rem;
  color: var(--yt-blue);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Clip Actions */
.yt-clip-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
}

.yt-mini-btn {
  background: var(--yt-bg-elevated);
  border: 1px solid var(--yt-border);
  color: var(--yt-text-primary);
  font-size: 0.72rem;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: var(--radius-xs);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.yt-mini-btn:hover {
  background: var(--yt-bg-hover);
}
.yt-mini-btn.btn-play {
  background: var(--yt-blue);
  color: #000;
  border-color: var(--yt-blue);
}
.yt-mini-btn.btn-play:hover {
  background: var(--yt-blue-hover);
}

.yt-mini-btn.active-mastered {
  background: rgba(43, 166, 64, 0.2);
  color: #34d399;
  border-color: rgba(43, 166, 64, 0.4);
}

/* Empty State */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 60px 20px;
  color: var(--yt-text-secondary);
}
.empty-icon {
  font-size: 44px;
  margin-bottom: 10px;
  opacity: 0.8;
}
.empty-state h3 {
  font-size: 1.05rem;
  color: #fff;
  font-weight: 700;
  margin-bottom: 6px;
}
.empty-state p {
  font-size: 0.82rem;
  max-width: 320px;
  margin-bottom: 16px;
}

/* ==========================================================================
   Modals & Notifications
   ========================================================================== */

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: none;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 200;
}
.modal-backdrop.active {
  display: flex;
  animation: fadeIn 0.2s ease-out;
}

.modal-box {
  background: var(--yt-bg-surface);
  border: 1px solid var(--yt-border);
  border-radius: var(--radius-md);
  width: 100%;
  max-width: 520px;
  padding: 24px;
  box-shadow: var(--yt-shadow);
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}
.modal-header h3 {
  font-size: 1.15rem;
  font-weight: 700;
}
.modal-close-btn {
  background: none;
  border: none;
  color: var(--yt-text-muted);
  font-size: 1.2rem;
  cursor: pointer;
}
.modal-close-btn:hover {
  color: #fff;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 18px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
}
.form-group label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--yt-text-secondary);
}
.form-input, .form-select, .form-textarea {
  width: 100%;
  background: var(--yt-bg-input);
  border: 1px solid var(--yt-border);
  border-radius: var(--radius-xs);
  color: var(--yt-text-primary);
  padding: 9px 12px;
  font-family: var(--font-sans);
  font-size: 0.88rem;
  outline: none;
}
.form-input:focus, .form-select:focus, .form-textarea:focus {
  border-color: var(--yt-blue);
}

.form-row-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

/* Toast System */
.toast-container {
  position: fixed;
  bottom: 24px;
  right: 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 300;
}

.toast {
  background: #212121;
  border: 1px solid var(--yt-border);
  padding: 12px 18px;
  border-radius: var(--radius-sm);
  box-shadow: var(--yt-shadow);
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.85rem;
  color: #fff;
  animation: slideInRight 0.25s ease-out;
}
.toast.success { border-left: 4px solid var(--yt-green); }
.toast.info { border-left: 4px solid var(--yt-blue); }
.toast.error { border-left: 4px solid var(--yt-red); }

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: scale(0.98); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes slideInRight {
  from { transform: translateX(100%); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

/* ==========================================================================
   Drawer Backdrop & Dropdown Menu Base Styles
   ========================================================================== */

.drawer-backdrop {
  display: none;
}

.drawer-drag-handle {
  display: none;
}

.drawer-close-btn {
  display: none;
  background: none;
  border: none;
  color: var(--yt-text-secondary);
  font-size: 1.2rem;
  cursor: pointer;
  padding: 4px 8px;
}
.yt-search-back-btn {
  display: none;
}
.yt-mob-search-trigger {
  display: none;
}

.yt-bottom-sheet {
  display: none;
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%) translateY(105%);
  width: 100%;
  max-width: 480px;
  max-height: 80vh;
  overflow-y: auto;
  z-index: 200;
  background: #181b22;
  border-top-left-radius: 20px;
  border-top-right-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-bottom: none;
  box-shadow: 0 -10px 40px rgba(0, 0, 0, 0.9);
  padding: 16px 20px 30px 20px;
  box-sizing: border-box;
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.yt-bottom-sheet.sheet-open {
  display: block !important;
  transform: translateX(-50%) translateY(0) !important;
}

.bottom-sheet-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}

.bottom-sheet-title {
  font-size: 1.05rem;
  font-weight: 800;
  color: #f1f1f1;
}

.sheet-section-label {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--yt-text-secondary);
  margin-bottom: 8px;
  display: block;
}

.sheet-speed-chips {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
  overflow-x: auto;
}

.sheet-speed-btn {
  flex: 1;
  padding: 8px 0;
  font-size: 0.85rem;
  font-weight: 700;
  border-radius: 8px;
  background: #272727;
  color: #f1f1f1;
  border: 1px solid rgba(255, 255, 255, 0.1);
  cursor: pointer;
}
.sheet-speed-btn.active {
  background: var(--yt-blue);
  color: #000;
  border-color: var(--yt-blue);
}

.sheet-menu-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sheet-menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  color: #f1f1f1;
  font-family: var(--font-sans);
  text-align: left;
  cursor: pointer;
  text-decoration: none;
  width: 100%;
  box-sizing: border-box;
  transition: background 0.15s ease;
}
.sheet-menu-item:hover, .sheet-menu-item:active {
  background: rgba(255, 255, 255, 0.12);
}

.sheet-item-icon {
  font-size: 1.3rem;
  width: 32px;
  text-align: center;
}

.sheet-item-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sheet-item-title {
  font-size: 0.9rem;
  font-weight: 700;
  color: #f1f1f1;
}

.sheet-item-sub {
  font-size: 0.72rem;
  color: #aaa;
}

.mobile-bottom-nav {
  display: none;
}

/* ==========================================================================
   Mobile & Tablet Responsiveness (100% True Mobile App Layout)
   ========================================================================== */

@media (max-width: 1100px) {
  .yt-watch-layout {
    grid-template-columns: 1fr;
    padding: 12px 14px;
    gap: 20px;
  }

  .yt-sidebar-header {
    top: 56px;
  }
}

@media (max-width: 768px) {
  html, body {
    width: 100% !important;
